-- ===================================================== 20261109000010_late_arrivals.sql
-- UniAttend 0010 — late arrivals: the lecturer has the final say.
--
-- After the grace period, a check-in that passes the QR/location/device checks is
-- recorded as 'late_pending' (shown grey: arrived, awaiting the lecturer) together
-- with how many minutes after the grace period the student arrived. The lecturer
-- accepts (-> late, counts as attended) or denies (-> absent). Anything still
-- undecided when the session closes is accepted.

alter table uniattend.attendance_records drop constraint if exists attendance_records_status_check;
alter table uniattend.attendance_records add constraint attendance_records_status_check check (status in
  ('present','absent','late','late_pending','excused','pending_verification','disputed'));
alter table uniattend.attendance_records
  add column if not exists minutes_late int check (minutes_late is null or minutes_late between 0 and 1440);
-- check_in() looks for the same device used by other students in the last 30 days.
-- Without this index that scans every record the institution wrote in 30 days.
create index if not exists attendance_records_device_recent on uniattend.attendance_records(institution_id, device_hash, created_at)
  where device_hash is not null;
create index if not exists attendance_records_late_pending on uniattend.attendance_records(session_id)
  where status = 'late_pending';

create or replace function uniattend.check_in(p_session uuid, p_code text, p_token text,
                                           p_gps jsonb, p_device_hash text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  s uniattend.class_sessions; st uniattend.institution_settings; v uniattend.venues; m uniattend.modules;
  stu uniattend.students; existing uniattend.attendance_records; rec uniattend.attendance_records;
  step bigint; method text; v_status text;
  reasons jsonb := '[]'::jsonb; layers jsonb := '{}'::jsonb;
  earned float8 := 0; possible float8 := 0; score int; outcome text;
  -- gps
  smp jsonb; n int := 0; wsum float8 := 0; lat float8 := 0; lng float8 := 0; acc_sum float8 := 0;
  acc float8; best_acc float8 := 'infinity'; accs float8[] := '{}'; w float8;
  signed float8; sigma float8; p float8; gps_pts float8; dist float8;
  -- device
  dev_pts float8; others int;
  -- lateness
  v_late int; v_title text; v_body text;
begin
  if uid is null then raise exception 'not signed in' using errcode = '42501'; end if;

  -- 1. Which session. By id (from the QR) or by typed code among the caller's institutions.
  if p_session is not null then
    select * into s from uniattend.class_sessions where id = p_session;
  elsif p_code is not null then
    select cs.* into s from uniattend.class_sessions cs
    join uniattend.students x on x.institution_id = cs.institution_id and x.user_id = uid
    join uniattend.module_enrolments e on e.module_id = cs.module_id and e.student_id = x.id and e.status = 'active'
    where cs.join_code = upper(trim(p_code)) and cs.status = 'open'
    limit 1;
  end if;
  if s is null then raise exception 'No open session matches that code.' using errcode = 'P0002'; end if;

  -- 2. Who, derived from the session's institution and auth.uid() — never from input.
  select * into stu from uniattend.students
   where institution_id = s.institution_id and user_id = uid and status = 'active' and deleted_at is null;
  if stu is null or not uniattend.has_role(s.institution_id, array['student']) then
    raise exception 'You are not registered as a student at this institution.' using errcode = '42501';
  end if;
  if not exists (select 1 from uniattend.module_enrolments
                 where module_id = s.module_id and student_id = stu.id and status = 'active') then
    raise exception 'You are not enrolled in this module.' using errcode = '42501';
  end if;
  if s.status <> 'open' or now() not between s.opens_at and s.closes_at then
    raise exception 'This session is not accepting check-ins.' using errcode = 'P0001';
  end if;
  if not uniattend.institution_can_operate(s.institution_id) then
    raise exception 'Attendance is unavailable for this institution right now.' using errcode = 'P0001';
  end if;

  -- 3. Rate limit: 5 attempts per student per session per minute.
  if (select count(*) from uniattend.attendance_verification_events
      where student_id = stu.id and session_id = s.id and created_at > now() - interval '1 minute') >= 5 then
    raise exception 'Too many attempts. Wait a minute and try again.' using errcode = 'P0001';
  end if;

  -- 4. Duplicate.
  select * into existing from uniattend.attendance_records where session_id = s.id and student_id = stu.id;
  if existing.id is not null and existing.status <> 'pending_verification' then
    insert into uniattend.attendance_verification_events (institution_id, session_id, student_id, outcome, score, layers, reasons)
    values (s.institution_id, s.id, stu.id, 'duplicate', coalesce(existing.score, 0), '{}', '["Already recorded"]');
    return jsonb_build_object('outcome', 'duplicate', 'status', existing.status, 'score', existing.score,
                              'reasons', jsonb_build_array('You are already recorded for this session.'));
  end if;

  select * into st from uniattend.institution_settings where institution_id = s.institution_id;
  select * into m from uniattend.modules where id = s.module_id;
  if s.venue_id is not null then select * into v from uniattend.venues where id = s.venue_id; end if;

  -- 5. Session proof layer (40). A valid live QR, or the typed code if allowed.
  possible := possible + 40;
  step := case when p_session is not null then uniattend.qr_verify(s.id, p_token) end;
  if step is not null then
    earned := earned + 40; method := 'qr';
    layers := layers || jsonb_build_object('qr', jsonb_build_object('points', 40, 'max', 40, 'step', step));
  elsif upper(trim(coalesce(p_code, ''))) = s.join_code and (st.allow_manual_code or not s.require_qr) then
    earned := earned + 15; method := 'code';
    reasons := reasons || '"Checked in with the typed code instead of scanning the live QR."';
    layers := layers || jsonb_build_object('qr', jsonb_build_object('points', 15, 'max', 40, 'typed_code', true));
  else
    reasons := reasons || to_jsonb(case when p_token is not null
      then 'The QR code had expired or was not valid. Scan the code currently on screen.'
      else 'No valid session code was provided.' end);
    insert into uniattend.attendance_verification_events (institution_id, session_id, student_id, outcome, score, layers, reasons)
    values (s.institution_id, s.id, stu.id, 'rejected', 0, jsonb_build_object('qr', jsonb_build_object('points', 0, 'max', 40)), reasons);
    return jsonb_build_object('outcome', 'rejected', 'status', null, 'score', 0, 'reasons', reasons);
  end if;

  -- 6. Location layer (40). Probability of being inside, given reported accuracy.
  if s.require_gps then
    possible := possible + 40;
    if p_gps is null or jsonb_typeof(p_gps->'samples') <> 'array' or jsonb_array_length(p_gps->'samples') = 0 then
      gps_pts := 0;
      reasons := reasons || '"Location was not shared, so presence at the venue could not be checked."';
      layers := layers || jsonb_build_object('gps', jsonb_build_object('points', 0, 'max', 40, 'shared', false));
    else
      for smp in select value from jsonb_array_elements(p_gps->'samples') limit 20 loop
        if jsonb_typeof(smp->'lat') = 'number' and jsonb_typeof(smp->'lng') = 'number' and jsonb_typeof(smp->'accuracy') = 'number'
           and (smp->>'lat')::float8 between -90 and 90 and (smp->>'lng')::float8 between -180 and 180
           and (smp->>'accuracy')::float8 > 0 then
          acc := (smp->>'accuracy')::float8;
          w := 1 / greatest(9, acc * acc);
          lat := lat + w * (smp->>'lat')::float8; lng := lng + w * (smp->>'lng')::float8; wsum := wsum + w;
          acc_sum := acc_sum + acc; best_acc := least(best_acc, acc); accs := accs || acc; n := n + 1;
        end if;
      end loop;
      if n = 0 then
        gps_pts := 0;
        reasons := reasons || '"Location data could not be read."';
        layers := layers || jsonb_build_object('gps', jsonb_build_object('points', 0, 'max', 40, 'shared', true, 'valid', false));
      else
        lat := lat / wsum; lng := lng / wsum;
        acc := greatest(3, least(acc_sum / n, best_acc));
        if v.polygon is not null then
          signed := uniattend.polygon_signed_distance_m(lat, lng, v.polygon);
        else
          signed := uniattend.geo_distance_m(lat, lng, v.lat, v.lng) - coalesce(v.radius_m, st.gps_default_radius_m);
        end if;
        sigma := greatest(4, acc * 0.6);
        p := 1 / (1 + exp(least(50, greatest(-50, 1.7 * signed / sigma))));
        gps_pts := 40 * p;
        if acc > st.gps_max_accuracy_m then
          gps_pts := least(gps_pts, 8);
          reasons := reasons || to_jsonb(format('Location was too imprecise to confirm (±%s m). Try near a window or with Wi-Fi on.', round(acc)));
        elsif p < 0.5 then
          reasons := reasons || to_jsonb(format('Location appears to be about %s m outside the venue (accuracy ±%s m).', round(greatest(signed, 0)), round(acc)));
        end if;
        -- Integrity: a run of identical, implausibly precise readings is what a spoofing app produces.
        if n >= 4 and (select count(distinct x) from unnest(accs) x) = 1 and best_acc <= 5 then
          gps_pts := least(gps_pts, 10);
          reasons := reasons || '"Location readings were unusually uniform and could not be relied on."';
        end if;
        dist := round(greatest(signed, 0)::numeric, 0);
        layers := layers || jsonb_build_object('gps', jsonb_build_object(
          'points', round(gps_pts::numeric, 1), 'max', 40, 'samples', n,
          'accuracy_m', round(acc::numeric, 0), 'outside_by_m', dist, 'p_inside', round(p::numeric, 2)));
      end if;
    end if;
    earned := earned + gps_pts;
  else
    layers := layers || jsonb_build_object('gps', jsonb_build_object('required', false));
  end if;

  -- 7. Device layer (20). Signals only; changing phones is normal and never blocks.
  possible := possible + 20;
  if p_device_hash is null or p_device_hash !~ '^[0-9a-f]{64}$' then
    dev_pts := 10; p_device_hash := null;
    reasons := reasons || '"This browser could not provide a device check."';
  elsif exists (select 1 from uniattend.attendance_records
                where session_id = s.id and device_hash = p_device_hash and student_id <> stu.id) then
    dev_pts := 0;
    reasons := reasons || '"This device has already been used to check in another student for this session."';
  else
    select count(distinct student_id) into others from uniattend.attendance_records
     where institution_id = s.institution_id and device_hash = p_device_hash and student_id <> stu.id
       and created_at > now() - interval '30 days';
    dev_pts := case when others >= 2 then 10 else 20 end;
    if others >= 2 then
      reasons := reasons || '"This device has recently been used by several students."';
    end if;
  end if;
  earned := earned + dev_pts;
  layers := layers || jsonb_build_object('device', jsonb_build_object('points', dev_pts, 'max', 20));

  -- 8. Verdict. A proven session is never turned into an absence by weak signals:
  -- below the accept threshold it goes to a person for review.
  score := round(100 * earned / possible);
  -- How late: whole minutes after the grace period ended, measured at the moment the
  -- live QR and location put the student in the venue.
  v_late := case when now() > s.late_after
                 then greatest(1, floor(extract(epoch from now() - s.late_after) / 60))::int end;
  if v_late is not null then
    reasons := reasons || to_jsonb(format('Arrived %s min after the grace period ended.%s', v_late,
      case when s.require_gps and coalesce(p, 0) >= 0.5 then ' Location confirmed in the venue at that time.' else '' end));
  end if;
  if score >= st.accept_score then
    outcome := 'accepted';
    -- A late arrival waits for the lecturer, who has the final say. If the lecturer has not
    -- denied it by the time the session closes, it counts as attended (late).
    v_status := case when v_late is not null then 'late_pending' else 'present' end;
  else
    outcome := 'review';
    v_status := 'pending_verification';
  end if;

  insert into uniattend.attendance_records as ar (institution_id, session_id, module_id, student_id, status, method,
                                               score, checked_in_at, device_hash, explanation, minutes_late)
  values (s.institution_id, s.id, s.module_id, stu.id, v_status, method, score, now(), p_device_hash, reasons, v_late)
  on conflict (session_id, student_id) do update
    set status = excluded.status, method = excluded.method, score = excluded.score,
        checked_in_at = excluded.checked_in_at, device_hash = excluded.device_hash, explanation = excluded.explanation,
        minutes_late = excluded.minutes_late
    where ar.status = 'pending_verification' and excluded.score > coalesce(ar.score, 0)
  returning * into rec;
  if rec.id is null then  -- an earlier pending attempt scored at least as well
    select * into rec from uniattend.attendance_records where session_id = s.id and student_id = stu.id;
  end if;

  insert into uniattend.attendance_evidence (institution_id, record_id, kind, data)
  select s.institution_id, rec.id, k, layers->k from unnest(array['qr','gps','device']) k where layers ? k;

  insert into uniattend.attendance_verification_events (institution_id, session_id, student_id, outcome, score, layers, reasons, token_step)
  values (s.institution_id, s.id, stu.id, outcome, score, layers, reasons, step);

  if rec.status = 'late_pending' then
    v_title := m.code || ': arrived ' || rec.minutes_late || ' min late';
    v_body := 'Your lecturer decides whether it counts. If it is not denied, it counts as attended (late).';
  elsif outcome = 'accepted' then
    v_title := m.code || ': you are checked in';
    v_body := 'Recorded as ' || replace(rec.status, '_', ' ') || '.';
  else
    v_title := m.code || ': check-in sent for review';
    v_body := 'Your lecturer will confirm it. You do not need to do anything else.';
  end if;
  insert into uniattend.notifications (institution_id, user_id, kind, title, body, link)
  values (s.institution_id, uid, case when outcome = 'accepted' then 'check_in_ok' else 'check_in_review' end,
          v_title, v_body, '/student/history');

  return jsonb_build_object('outcome', outcome, 'status', rec.status, 'score', rec.score,
                            'reasons', reasons, 'module_code', m.code, 'session_title', s.title,
                            'minutes_late', rec.minutes_late, 'checked_in_at', rec.checked_in_at,
                            'opens_at', s.opens_at, 'late_after', s.late_after);
end $$;

create or replace function uniattend.close_session(p_session uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare s uniattend.class_sessions; n_absent int; n_late_auto int;
begin
  select * into s from uniattend.class_sessions where id = p_session for update;
  if s is null or not (uniattend.teaches_module(s.module_id) or uniattend.is_inst_admin(s.institution_id)) then
    raise exception 'not your session' using errcode = '42501';
  end if;
  if s.status <> 'open' then raise exception 'session is already %', s.status; end if;

  update uniattend.class_sessions set status = 'closed', closed_at = now(),
         closes_at = least(closes_at, now()) where id = p_session;
  delete from uniattend.session_secrets where session_id = p_session;
  delete from uniattend.acoustic_submissions sub using uniattend.acoustic_windows w
   where sub.window_id = w.id and w.session_id = p_session;

  -- Late arrivals the lecturer did not deny count as attended.
  update uniattend.attendance_records
     set status = 'late',
         override_note = 'Late arrival accepted automatically: the lecturer did not deny it before the session closed.'
   where session_id = p_session and status = 'late_pending';
  get diagnostics n_late_auto = row_count;

  -- Absence is recorded only once the session is over, never pre-emptively.
  insert into uniattend.attendance_records (institution_id, session_id, module_id, student_id, status, method, explanation)
  select s.institution_id, s.id, s.module_id, e.student_id, 'absent', 'system',
         '["No check-in was received before the session closed."]'::jsonb
  from uniattend.module_enrolments e
  where e.module_id = s.module_id and e.status = 'active'
  on conflict (session_id, student_id) do nothing;
  get diagnostics n_absent = row_count;

  perform uniattend.write_audit(s.institution_id, 'close', 'class_sessions', s.id::text,
                             jsonb_build_object('absent', n_absent, 'late_auto_accepted', n_late_auto));
  return (select jsonb_build_object(
    'absent', n_absent,
    'late_auto_accepted', n_late_auto,
    'present', count(*) filter (where status = 'present'),
    'late', count(*) filter (where status = 'late'),
    'pending', count(*) filter (where status = 'pending_verification'))
    from uniattend.attendance_records where session_id = p_session);
end $$;

-- Accept or deny late arrivals, one student or many at once. A decision can be
-- changed: a late arrival already accepted or denied may be flipped.
create or replace function uniattend.decide_late(p_session uuid, p_students uuid[], p_accept boolean, p_note text default null)
returns int language plpgsql security definer set search_path = '' as $$
declare s uniattend.class_sessions; r uniattend.attendance_records; n int := 0; v_note text;
begin
  select * into s from uniattend.class_sessions where id = p_session;
  if s is null or not (uniattend.teaches_module(s.module_id) or uniattend.is_inst_admin(s.institution_id)) then
    raise exception 'only the module lecturer or an administrator may decide late arrivals' using errcode = '42501';
  end if;
  if p_accept is null or coalesce(cardinality(p_students), 0) = 0 or cardinality(p_students) > 2000 then
    raise exception 'choose between 1 and 2000 students';
  end if;
  v_note := coalesce(nullif(left(trim(p_note), 500), ''),
                     case when p_accept then 'Late arrival accepted by the lecturer.' else 'Late arrival denied by the lecturer.' end);

  for r in
    update uniattend.attendance_records ar
       set status = case when p_accept then 'late' else 'absent' end,
           overridden_by = auth.uid(), overridden_at = now(), override_note = v_note
     where ar.session_id = p_session and ar.student_id = any(p_students)
       and (ar.status = 'late_pending' or (ar.minutes_late is not null and ar.status in ('late','absent')))
    returning ar.*
  loop
    n := n + 1;
    insert into uniattend.attendance_evidence (institution_id, record_id, kind, data)
    values (s.institution_id, r.id, 'manual', jsonb_build_object('status', r.status, 'note', v_note, 'by', auth.uid(),
                                                                 'late_decision', case when p_accept then 'accepted' else 'denied' end));
    insert into uniattend.notifications (institution_id, user_id, kind, title, body, link)
    select s.institution_id, st.user_id, 'attendance_corrected',
           case when p_accept then 'Late arrival accepted' else 'Late arrival not accepted' end,
           s.title || ': ' || case when p_accept then 'counted as attended (late, ' || r.minutes_late || ' min).'
                                   else 'recorded as absent. You can dispute this from your history.' end,
           '/student/history'
    from uniattend.students st where st.id = r.student_id and st.user_id is not null;
  end loop;

  perform uniattend.write_audit(s.institution_id, case when p_accept then 'late_accept' else 'late_deny' end,
                             'class_sessions', s.id::text, jsonb_build_object('students', n));
  return n;
end $$;

revoke all on function uniattend.decide_late(uuid, uuid[], boolean, text) from public, anon;
grant execute on function uniattend.decide_late(uuid, uuid[], boolean, text) to authenticated;


-- ===================================================== 20261109000011_push_notifications.sql
-- UniAttend 0011 — phone notifications.
--
-- Every notification row (attendance open, check-in results, late decisions,
-- corrections, disputes) can now also be pushed to the person's phone or browser.
-- New sources of notifications:
--   * class reminders, queued shortly before each timetabled class;
--   * announcements, fanned out to their audience when published.
-- A sender (the app's /api/push/dispatch, called every minute by pg_cron) claims
-- unsent notifications with a shared secret and delivers them with Web Push.

-- ------------------------------------------------------------ subscriptions
create table uniattend.push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  endpoint      text not null unique check (endpoint ~ '^https://' and length(endpoint) <= 1000),
  p256dh        text not null check (length(p256dh) between 20 and 200),
  auth          text not null check (length(auth) between 8 and 100),
  user_agent    text check (user_agent is null or length(user_agent) <= 300),
  -- What this device wants: class reminders, announcements, attendance updates.
  prefs         jsonb not null default '{"classes": true, "announcements": true, "attendance": true}'::jsonb,
  created_at    timestamptz not null default now(),
  last_sent_at  timestamptz
);
create index push_subscriptions_user on uniattend.push_subscriptions(user_id);
alter table uniattend.push_subscriptions enable row level security;
create policy push_subscriptions_own on uniattend.push_subscriptions for select to authenticated
  using (user_id = (select auth.uid()));
create policy push_subscriptions_delete on uniattend.push_subscriptions for delete to authenticated
  using (user_id = (select auth.uid()));
-- Inserts and updates go through save_push_subscription(), which also moves a
-- device from a previous account to the one now signed in.

-- The sender's shared secret, stored as a hash. No policies: only functions read it.
create table uniattend.push_config (
  id             int primary key default 1 check (id = 1),
  secret_sha256  text not null check (secret_sha256 ~ '^[0-9a-f]{64}$'),
  reminder_minutes int not null default 15 check (reminder_minutes between 5 and 120),
  updated_at     timestamptz not null default now()
);
alter table uniattend.push_config enable row level security;

-- ------------------------------------------------------- notifications
alter table uniattend.notifications add column if not exists pushed_at timestamptz;
alter table uniattend.notifications add column if not exists dedupe_key text;
create unique index if not exists notifications_dedupe on uniattend.notifications(dedupe_key) where dedupe_key is not null;
create index if not exists notifications_unpushed on uniattend.notifications(created_at) where pushed_at is null;
-- Nothing already in people's inboxes is pushed.
update uniattend.notifications set pushed_at = created_at where pushed_at is null;

-- ---------------------------------------------------------------- functions

create or replace function uniattend.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text,
                                                            p_user_agent text default null, p_prefs jsonb default null)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_prefs jsonb;
begin
  if auth.uid() is null then raise exception 'not signed in' using errcode = '42501'; end if;
  v_prefs := jsonb_build_object(
    'classes',       coalesce((p_prefs->>'classes')::boolean, true),
    'announcements', coalesce((p_prefs->>'announcements')::boolean, true),
    'attendance',    coalesce((p_prefs->>'attendance')::boolean, true));
  insert into uniattend.push_subscriptions as ps (user_id, endpoint, p256dh, auth, user_agent, prefs)
  values (auth.uid(), p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300), v_prefs)
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth,
        user_agent = excluded.user_agent, prefs = excluded.prefs
  returning ps.id into v_id;
  return v_id;
end $$;

create or replace function uniattend.set_push_secret(p_secret text, p_reminder_minutes int default 15)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not uniattend.is_super_admin() then raise exception 'super admin only' using errcode = '42501'; end if;
  if length(coalesce(p_secret, '')) < 32 then raise exception 'use a secret of at least 32 characters'; end if;
  insert into uniattend.push_config (id, secret_sha256, reminder_minutes)
  values (1, encode(extensions.digest(p_secret, 'sha256'), 'hex'), p_reminder_minutes)
  on conflict (id) do update set secret_sha256 = excluded.secret_sha256,
    reminder_minutes = excluded.reminder_minutes, updated_at = now();
end $$;

create or replace function uniattend.push_secret_ok(p_secret text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from uniattend.push_config
                 where id = 1 and secret_sha256 = encode(extensions.digest(coalesce(p_secret, ''), 'sha256'), 'hex'));
$$;

-- Reminders for classes starting within the next N minutes (South African time),
-- one per student per class per day. Safe to call as often as you like.
create or replace function uniattend.queue_class_reminders(p_minutes int default 15)
returns int language plpgsql security definer set search_path = '' as $$
declare v_now timestamp := now() at time zone 'Africa/Johannesburg'; n int;
begin
  insert into uniattend.notifications (institution_id, user_id, kind, title, body, link, dedupe_key)
  select t.institution_id, s.user_id, 'class_reminder',
         m.code || ' starts at ' || to_char(t.starts_at, 'HH24:MI'),
         initcap(t.kind) || ' · ' || coalesce(v.name, 'venue not set') || coalesce(' · ' || l.full_name, '')
           || ' · until ' || to_char(t.ends_at, 'HH24:MI'),
         '/student/map',
         'class:' || t.id || ':' || v_now::date || ':' || s.user_id
  from uniattend.timetables t
  join uniattend.modules m on m.id = t.module_id and m.deleted_at is null
  join uniattend.institutions i on i.id = t.institution_id and i.status = 'active'
  join uniattend.module_enrolments e on e.module_id = t.module_id and e.status = 'active'
  join uniattend.students s on s.id = e.student_id and s.user_id is not null and s.status = 'active' and s.deleted_at is null
  left join uniattend.venues v on v.id = t.venue_id
  left join uniattend.lecturers l on l.id = t.lecturer_id
  where t.weekday = extract(isodow from v_now)::int
    and t.starts_at >  v_now::time
    and t.starts_at <= (v_now + make_interval(mins => least(120, greatest(1, p_minutes))))::time
    and (v_now + make_interval(mins => least(120, greatest(1, p_minutes))))::date = v_now::date
  on conflict (dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- Announcements reach their audience's inboxes (and phones) when published.
create or replace function uniattend.fan_out_announcement()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.published_at > now() + interval '1 minute' then return new; end if;  -- scheduled ones are not supported yet
  insert into uniattend.notifications (institution_id, user_id, kind, title, body, link, dedupe_key)
  select distinct on (r.user_id) coalesce(new.institution_id, r.institution_id), r.user_id, 'announcement', new.title,
         left(new.body, 500), '/notifications', 'ann:' || new.id || ':' || r.user_id
  from uniattend.user_roles r
  where r.status = 'active'
    and (new.institution_id is null or r.institution_id = new.institution_id)
    and case new.audience
          when 'students'  then r.role = 'student'
          when 'lecturers' then r.role = 'lecturer'
          when 'admins'    then r.role in ('institution_admin', 'super_admin')
          else true end
  on conflict (dedupe_key) where dedupe_key is not null do nothing;
  return new;
end $$;
create trigger announcements_fan_out after insert on uniattend.announcements
  for each row execute function uniattend.fan_out_announcement();

-- The sender claims what to deliver. Queues due class reminders first, skips
-- anything older than an hour, and marks what it returns as pushed.
create or replace function uniattend.push_claim(p_secret text, p_limit int default 500)
returns table (notification_id uuid, kind text, title text, body text, link text, created_at timestamptz,
               institution_name text, logo_url text, endpoint text, p256dh text, auth text)
language plpgsql security definer set search_path = '' as $$
declare v_minutes int; v_ids uuid[];
begin
  if not uniattend.push_secret_ok(p_secret) then raise exception 'not allowed' using errcode = '42501'; end if;
  select reminder_minutes into v_minutes from uniattend.push_config where id = 1;
  perform uniattend.queue_class_reminders(v_minutes);

  update uniattend.notifications n set pushed_at = now()
   where n.pushed_at is null and n.created_at < now() - interval '1 hour';

  with picked as (
    select n.id from uniattend.notifications n
    where n.pushed_at is null
    order by n.created_at
    limit least(greatest(coalesce(p_limit, 500), 1), 2000)
    for update skip locked),
  claimed as (
    update uniattend.notifications n set pushed_at = now()
      from picked where n.id = picked.id
    returning n.id)
  select coalesce(array_agg(id), '{}') into v_ids from claimed;

  return query
  select n.id, n.kind, n.title, n.body, n.link, n.created_at,
         coalesce(nullif(i.theme->'header'->>'title', ''), i.name),
         nullif(i.theme->'header'->>'logoUrl', ''),
         ps.endpoint, ps.p256dh, ps.auth
  from uniattend.notifications n
  join uniattend.push_subscriptions ps on ps.user_id = n.user_id
  left join uniattend.institutions i on i.id = n.institution_id
  where n.id = any(v_ids)
    and coalesce((ps.prefs->>(case when n.kind = 'class_reminder' then 'classes'
                                   when n.kind = 'announcement' then 'announcements'
                                   else 'attendance' end))::boolean, true);
end $$;

-- A subscription the push service says is gone (404/410).
create or replace function uniattend.push_forget(p_secret text, p_endpoint text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not uniattend.push_secret_ok(p_secret) then raise exception 'not allowed' using errcode = '42501'; end if;
  delete from uniattend.push_subscriptions where endpoint = p_endpoint;
end $$;

create or replace function uniattend.push_sent(p_secret text, p_endpoints text[])
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not uniattend.push_secret_ok(p_secret) then raise exception 'not allowed' using errcode = '42501'; end if;
  update uniattend.push_subscriptions set last_sent_at = now() where endpoint = any(p_endpoints);
end $$;

-- ------------------------------------------------------------------ grants
do $$
declare f text;
begin
  foreach f in array array[
    'save_push_subscription(text,text,text,text,jsonb)', 'set_push_secret(text,integer)', 'push_secret_ok(text)',
    'queue_class_reminders(integer)', 'fan_out_announcement()', 'push_claim(text,integer)',
    'push_forget(text,text)', 'push_sent(text,text[])'] loop
    execute format('revoke all on function uniattend.%s from public, anon', f);
  end loop;
end $$;
grant execute on function uniattend.save_push_subscription(text,text,text,text,jsonb) to authenticated;
grant execute on function uniattend.set_push_secret(text,integer) to authenticated;
-- The sender calls these with the publishable key and the shared secret.
grant execute on function uniattend.push_claim(text,integer) to anon, authenticated;
grant execute on function uniattend.push_forget(text,text) to anon, authenticated;
grant execute on function uniattend.push_sent(text,text[]) to anon, authenticated;

-- "Send me a test" from the notification settings.
create or replace function uniattend.push_test()
returns void language plpgsql security definer set search_path = '' as $$
declare v_inst uuid;
begin
  if auth.uid() is null then raise exception 'not signed in' using errcode = '42501'; end if;
  if (select count(*) from uniattend.notifications where user_id = auth.uid() and kind = 'test'
        and created_at > now() - interval '1 minute') >= 3 then
    raise exception 'Wait a minute before sending another test.' using errcode = 'P0001';
  end if;
  select institution_id into v_inst from uniattend.user_roles where user_id = auth.uid() and status = 'active'
   order by institution_id nulls last limit 1;
  insert into uniattend.notifications (institution_id, user_id, kind, title, body, link)
  values (v_inst, auth.uid(), 'test', 'Notifications are on', 'You''ll get class reminders, announcements and attendance updates here.', '/notifications');
end $$;
revoke all on function uniattend.push_test() from public, anon;
grant execute on function uniattend.push_test() to authenticated;


-- ===================================================== 20261110000012_security_hardening.sql
-- 0012 — security review fixes (2026-11-10), on top of the uniattend schema.
--
-- 2. (app code) open redirect after sign-in / email links: see src/lib/safe-redirect.ts
-- 3. grant_role only targets accounts with a confirmed email, matching
--    link_my_accounts, so a pre-registered (squatted) address cannot receive a role.
-- 4. apply_paystack_payment: claims the payment and extends the subscription in
--    one transaction, so concurrent webhook deliveries apply a payment once.
-- (Fix 1 from the review, explicit table grants, is already covered here by the
--  uniattend schema and its default privileges in 0001.)
-- --------------------------------------------- 3. confirmed accounts only

create or replace function uniattend.grant_role(p_inst uuid, p_email text, p_role text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare target uuid; confirmed timestamptz; rid uuid;
begin
  if p_role = 'super_admin' then
    if not uniattend.is_super_admin() then raise exception 'super admin only' using errcode = '42501'; end if;
    p_inst := null;
  else
    if p_role not in ('institution_admin','lecturer','student') then raise exception 'bad role'; end if;
    if not uniattend.is_inst_admin(p_inst) then raise exception 'institution admin only' using errcode = '42501'; end if;
  end if;
  select id, email_confirmed_at into target, confirmed from auth.users where lower(email) = lower(trim(p_email));
  if target is null then raise exception 'No account uses that email yet. Ask them to sign up first.'; end if;
  if confirmed is null then
    raise exception 'That account has not confirmed its email yet. Ask them to click the link in their confirmation email, then try again.';
  end if;
  insert into uniattend.user_roles (user_id, institution_id, role, granted_by)
  values (target, p_inst, p_role, auth.uid())
  on conflict (user_id, institution_id, role) do update set status = 'active'
  returning id into rid;
  return rid;
end $$;

-- ------------------------------------------------- 4. Paystack, exactly once

-- Called only by the paystack-webhook Edge Function (service_role) AFTER it has
-- verified the signature and re-verified the transaction with Paystack.
-- Returns 'applied' | 'duplicate' | 'mismatch'.
create or replace function uniattend.apply_paystack_payment(
  p_institution uuid, p_plan_code text, p_reference text, p_amount bigint, p_currency text)
returns text language plpgsql security invoker set search_path = '' as $$
declare
  v_plan uniattend.subscription_plans;
  v_payment uuid;
  v_sub uniattend.institution_subscriptions;
  v_until timestamptz;
begin
  select * into v_plan from uniattend.subscription_plans where code = p_plan_code;
  if v_plan.id is null or v_plan.price_cents is null
     or p_amount is distinct from v_plan.price_cents or p_currency is distinct from v_plan.currency then
    -- Keep a record for a human to look at, but grant nothing.
    insert into uniattend.payments (institution_id, provider, provider_ref, amount_cents, currency, status)
    values (p_institution, 'paystack', p_reference, greatest(coalesce(p_amount, 0), 0), coalesce(p_currency, 'ZAR'), 'failed')
    on conflict (provider, provider_ref) do nothing;
    return 'mismatch';
  end if;

  -- Claim the payment. The unique (provider, provider_ref) row lock means only one
  -- delivery can create it or move it from 'pending' to 'succeeded'; every other
  -- delivery gets no row back and stops here.
  insert into uniattend.payments as pay (institution_id, provider, provider_ref, amount_cents, currency, status, verified_at)
  values (p_institution, 'paystack', p_reference, p_amount, p_currency, 'succeeded', now())
  on conflict (provider, provider_ref) do update
    set status = 'succeeded', amount_cents = excluded.amount_cents,
        currency = excluded.currency, verified_at = excluded.verified_at
    where pay.status = 'pending' and pay.institution_id = excluded.institution_id
  returning pay.id into v_payment;
  if v_payment is null then return 'duplicate'; end if;

  select * into v_sub from uniattend.institution_subscriptions
  where institution_id = p_institution and status in ('trialing','active','past_due','suspended')
  order by current_period_end desc limit 1
  for update;

  -- Extend from the later of "now" and the current paid-up date.
  v_until := greatest(coalesce(v_sub.current_period_end, now()), now())
             + case v_plan.billing_interval when 'year' then interval '1 year' else interval '1 month' end;

  if v_sub.id is not null then
    update uniattend.institution_subscriptions
    set plan_id = v_plan.id, status = 'active', current_period_end = v_until
    where id = v_sub.id;
  else
    insert into uniattend.institution_subscriptions (institution_id, plan_id, status, current_period_end)
    values (p_institution, v_plan.id, 'active', v_until)
    returning * into v_sub;
  end if;
  update uniattend.payments set subscription_id = v_sub.id where id = v_payment;
  return 'applied';
end $$;

-- New functions are executable by PUBLIC by default; lock this one to the server.
revoke all on function uniattend.apply_paystack_payment(uuid, text, text, bigint, text) from public, anon, authenticated;
grant execute on function uniattend.apply_paystack_payment(uuid, text, text, bigint, text) to service_role;


-- ===================================================== 20261110000013_campus_location_sharing.sql
-- 0013 — campus location sharing and class navigation (2026-11-10)
--
-- Location is personal information under POPIA. The design keeps it minimal:
--   * Off until the institution enables it AND the student gives consent.
--   * Only the LATEST position is kept: one row per student, no history.
--   * The row is deleted as soon as the student is off campus (unless they
--     turned on safety sharing themselves), stops sharing, or withdraws consent.
--     Positions not refreshed for 12 hours are purged.
--   * Only the student and their own institution's admins can read it.
--   * Nobody writes the table directly; report_location() decides on/off campus
--     on the server, so a modified app cannot keep sharing off campus silently.

-- ------------------------------------------------------------ schema

-- Campus outlines already exist (campuses.outline, migration 0009); report_location uses them.

alter table uniattend.institution_settings
  add column location_sharing_enabled boolean not null default false,
  add column location_interval_s      int not null default 60 check (location_interval_s between 15 and 900);

create table uniattend.location_consents (
  institution_id uuid not null references uniattend.institutions(id) on delete cascade,
  user_id        uuid not null references auth.users(id) on delete cascade,
  notice_version text not null,
  granted_at     timestamptz not null default now(),
  withdrawn_at   timestamptz,
  primary key (institution_id, user_id)
);

create table uniattend.live_locations (
  institution_id uuid not null references uniattend.institutions(id) on delete cascade,
  user_id        uuid not null references auth.users(id) on delete cascade,
  lat            double precision not null check (lat between -90 and 90),
  lng            double precision not null check (lng between -180 and 180),
  accuracy_m     real not null check (accuracy_m > 0 and accuracy_m <= 5000),
  on_campus      boolean not null,
  campus_id      uuid,
  mode           text not null check (mode in ('campus','safety')),
  updated_at     timestamptz not null default now(),
  primary key (institution_id, user_id),
  foreign key (institution_id, campus_id) references uniattend.campuses(institution_id, id) on delete set null (campus_id)
);
create index live_locations_fresh on uniattend.live_locations (institution_id, updated_at);

-- ------------------------------------------------------------ access

alter table uniattend.location_consents enable row level security;
alter table uniattend.live_locations enable row level security;

create policy location_consents_select on uniattend.location_consents for select to authenticated
  using (user_id = (select auth.uid()) or uniattend.is_inst_admin(institution_id));
create policy live_locations_select on uniattend.live_locations for select to authenticated
  using (user_id = (select auth.uid()) or uniattend.is_inst_admin(institution_id));
-- No insert/update/delete policies: all writes go through the functions below.

-- The uniattend schema gives anon/authenticated full table privileges by default
-- (0001). For location data take them back: users may only READ (RLS above
-- narrows to own row / own institution), anon gets nothing, and every write goes
-- through the functions below.
revoke insert, update, delete, truncate on uniattend.location_consents, uniattend.live_locations from anon, authenticated;
revoke select on uniattend.location_consents, uniattend.live_locations from anon;

-- ------------------------------------------------------------ functions

create or replace function uniattend.set_location_consent(p_inst uuid, p_give boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  if not uniattend.has_role(p_inst, array['student']) then raise exception 'students only' using errcode = '42501'; end if;
  if p_give then
    insert into uniattend.location_consents (institution_id, user_id, notice_version)
    values (p_inst, uid, 'campus-location-v1')
    on conflict (institution_id, user_id) do update
      set notice_version = excluded.notice_version, granted_at = now(), withdrawn_at = null;
  else
    update uniattend.location_consents set withdrawn_at = now() where institution_id = p_inst and user_id = uid;
    delete from uniattend.live_locations where institution_id = p_inst and user_id = uid;
  end if;
end $$;

-- Called by the student's phone every location_interval_s seconds while sharing.
create or replace function uniattend.report_location(
  p_inst uuid, p_lat float8, p_lng float8, p_accuracy float8, p_safety boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  c record; d float8; best float8;
  v_campus uuid; v_name text; inside boolean := false;
  v_mode text;
begin
  if uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  if not uniattend.has_role(p_inst, array['student']) then raise exception 'students only' using errcode = '42501'; end if;

  if not exists (select 1 from uniattend.institution_settings s
                 where s.institution_id = p_inst and s.location_sharing_enabled) then
    delete from uniattend.live_locations where institution_id = p_inst and user_id = uid;
    return jsonb_build_object('stored', false, 'reason', 'disabled');
  end if;
  if not exists (select 1 from uniattend.location_consents k
                 where k.institution_id = p_inst and k.user_id = uid and k.withdrawn_at is null) then
    raise exception 'Agree to campus location sharing first.' using errcode = '42501';
  end if;
  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180
     or p_accuracy is null or p_accuracy <= 0 or p_accuracy > 5000 then
    raise exception 'That location reading is not valid.';
  end if;

  -- On campus = inside any campus boundary (signed distance <= 0).
  for c in select cp.id, cp.name, cp.outline from uniattend.campuses cp
           where cp.institution_id = p_inst and cp.deleted_at is null and cp.outline is not null loop
    d := uniattend.polygon_signed_distance_m(p_lat, p_lng, c.outline);
    if d <= 0 and (best is null or d < best) then
      best := d; v_campus := c.id; v_name := c.name; inside := true;
    end if;
  end loop;

  -- Housekeeping: a position nobody refreshed for 12 hours is gone.
  delete from uniattend.live_locations where institution_id = p_inst and updated_at < now() - interval '12 hours';

  if not inside and not coalesce(p_safety, false) then
    delete from uniattend.live_locations where institution_id = p_inst and user_id = uid;
    return jsonb_build_object('stored', false, 'on_campus', false, 'reason', 'off_campus');
  end if;

  v_mode := case when inside then 'campus' else 'safety' end;
  insert into uniattend.live_locations as l (institution_id, user_id, lat, lng, accuracy_m, on_campus, campus_id, mode, updated_at)
  values (p_inst, uid, p_lat, p_lng, p_accuracy, inside, v_campus, v_mode, now())
  on conflict (institution_id, user_id) do update
    set lat = excluded.lat, lng = excluded.lng, accuracy_m = excluded.accuracy_m, on_campus = excluded.on_campus,
        campus_id = excluded.campus_id, mode = excluded.mode, updated_at = excluded.updated_at;
  return jsonb_build_object('stored', true, 'on_campus', inside, 'campus', v_name, 'mode', v_mode);
end $$;

create or replace function uniattend.stop_location_sharing(p_inst uuid)
returns void language sql security definer set search_path = '' as $$
  delete from uniattend.live_locations where institution_id = p_inst and user_id = auth.uid();
$$;

-- Admin live map. SECURITY INVOKER: RLS on live_locations and students applies,
-- so an admin sees their institution and a student sees only themselves.
create or replace function uniattend.campus_live_locations(p_inst uuid)
returns table (user_id uuid, full_name text, student_number text, lat float8, lng float8, accuracy_m real,
               on_campus boolean, campus_name text, mode text, updated_at timestamptz)
language sql stable security invoker set search_path = '' as $$
  select l.user_id, coalesce(nullif(st.full_name, ''), p.full_name), st.student_number,
         l.lat, l.lng, l.accuracy_m, l.on_campus, c.name, l.mode, l.updated_at
  from uniattend.live_locations l
  left join uniattend.students st on st.institution_id = l.institution_id and st.user_id = l.user_id and st.deleted_at is null
  left join uniattend.profiles p on p.id = l.user_id
  left join uniattend.campuses c on c.id = l.campus_id
  where l.institution_id = p_inst and l.updated_at > now() - interval '12 hours'
  order by l.updated_at desc;
$$;

-- A student's upcoming classes with the venue location, for navigation.
-- Timetables store a weekday + local time; the institution's timezone turns
-- that into real timestamps. SECURITY INVOKER: only the student's own enrolments.
create or replace function uniattend.my_next_classes(p_inst uuid, p_limit int default 5)
returns table (module_code text, module_title text, venue_id uuid, venue_name text, venue_code text,
               lat float8, lng float8, radius_m int, starts_at timestamptz, ends_at timestamptz)
language sql stable security invoker set search_path = '' as $$
  with tz as (
    select coalesce((select i.timezone from uniattend.institutions i where i.id = p_inst), 'Africa/Johannesburg') as zone
  ), clock as (
    select (now() at time zone (select zone from tz)) as local_now
  ), me as (
    select s.id from uniattend.students s
    where s.institution_id = p_inst and s.user_id = auth.uid() and s.deleted_at is null
  ), slots as (
    select t.module_id, t.venue_id, t.starts_at as t_start, t.ends_at as t_end,
           (select local_now from clock)::date
             + ((t.weekday - extract(isodow from (select local_now from clock))::int + 7) % 7) as day
    from uniattend.timetables t
    join uniattend.module_enrolments e
      on e.institution_id = t.institution_id and e.module_id = t.module_id and e.status = 'active'
    where t.institution_id = p_inst and e.student_id in (select id from me)
  ), occurrences as (
    -- a class that already ended today moves to the same weekday next week
    select sl.*, case when sl.day = (select local_now from clock)::date
                       and sl.t_end < (select local_now from clock)::time
                      then sl.day + 7 else sl.day end as on_day
    from slots sl
  )
  select m.code, m.title, v.id, v.name, v.code, v.lat, v.lng, v.radius_m,
         ((o.on_day + o.t_start) at time zone (select zone from tz)),
         ((o.on_day + o.t_end) at time zone (select zone from tz))
  from occurrences o
  join uniattend.modules m on m.id = o.module_id
  left join uniattend.venues v on v.id = o.venue_id and v.deleted_at is null
  order by 9
  limit greatest(1, least(coalesce(p_limit, 5), 20));
$$;

-- New functions are executable by PUBLIC by default (see 0005's note). Lock them
-- down, then allow signed-in users; each function checks role/consent itself.
do $$
declare fn text;
begin
  foreach fn in array array[
    'set_location_consent(uuid,boolean)', 'report_location(uuid,float8,float8,float8,boolean)',
    'stop_location_sharing(uuid)', 'campus_live_locations(uuid)', 'my_next_classes(uuid,int)']
  loop
    execute format('revoke all on function uniattend.%s from public, anon', fn);
    execute format('grant execute on function uniattend.%s to authenticated', fn);
  end loop;
end $$;


-- ===================================================== 20261111000014_attendance_register.sql
-- UniAttend 0014 — the lecturer's register: configurable statuses, bulk save, change history.
--
-- * attendance_statuses: an institution's own statuses ("Left early", "Medical",
--   "Field trip"...), each with a colour and a CATEGORY that decides how it counts:
--     present/late → attended, absent → absent, excused → left out of the percentage.
--   Records keep the category in attendance_records.status, so every existing
--   report, dashboard and percentage keeps working unchanged.
-- * save_register(): the lecturer saves many students at once, in one transaction.
-- * Every manual change keeps its history (from, to, who, when, why) in
--   attendance_evidence; record_history() returns it.

-- ---------------------------------------------------------------- statuses
create table uniattend.attendance_statuses (
  id             uuid primary key default gen_random_uuid(),
  institution_id uuid not null references uniattend.institutions(id) on delete cascade,
  name           text not null check (length(trim(name)) between 2 and 40),
  color          text not null default '#64748b' check (color ~ '^#[0-9a-fA-F]{6}$'),
  description    text check (description is null or length(description) <= 200),
  category       text not null check (category in ('present','late','absent','excused')),
  sort_order     int not null default 100,
  active         boolean not null default true,
  created_at     timestamptz not null default now(),
  unique (institution_id, id)
);
create unique index attendance_statuses_name on uniattend.attendance_statuses(institution_id, lower(name));
alter table uniattend.attendance_statuses enable row level security;
create policy attendance_statuses_select on uniattend.attendance_statuses for select to authenticated
  using (uniattend.is_member(institution_id) or uniattend.is_super_admin());
create policy attendance_statuses_write on uniattend.attendance_statuses for all to authenticated
  using (uniattend.is_inst_admin(institution_id)) with check (uniattend.is_inst_admin(institution_id));

alter table uniattend.attendance_records add column if not exists custom_status_id uuid;
alter table uniattend.attendance_records
  add constraint attendance_records_custom_status_fk foreign key (institution_id, custom_status_id)
  references uniattend.attendance_statuses(institution_id, id) on delete set null (custom_status_id);

-- Every institution starts with "Left early" (counts as attended, shown amber).
create or replace function uniattend.seed_attendance_statuses()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into uniattend.attendance_statuses (institution_id, name, color, description, category, sort_order)
  values (new.id, 'Left early', '#d97706', 'Attended but left before the end of the class.', 'present', 10)
  on conflict do nothing;
  return new;
end $$;
create trigger institutions_seed_statuses after insert on uniattend.institutions
  for each row execute function uniattend.seed_attendance_statuses();
insert into uniattend.attendance_statuses (institution_id, name, color, description, category, sort_order)
select i.id, 'Left early', '#d97706', 'Attended but left before the end of the class.', 'present', 10
from uniattend.institutions i
on conflict do nothing;

-- ---------------------------------------------------------------- bulk save
-- p_entries: [{"student": uuid, "status": "present|late|absent|excused", "custom": uuid|null, "note": text|null}, ...]
-- Unchanged entries are skipped. Corrections after the session has closed need a reason.
create or replace function uniattend.save_register(p_session uuid, p_entries jsonb, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  s uniattend.class_sessions; e jsonb; v_student uuid; v_status text; v_custom uuid; v_note text;
  prev uniattend.attendance_records; r uniattend.attendance_records; v_by text; uid uuid; changed int := 0; skipped int := 0;
begin
  select * into s from uniattend.class_sessions where id = p_session;
  if s is null or not (uniattend.teaches_module(s.module_id) or uniattend.is_inst_admin(s.institution_id)) then
    raise exception 'only the module lecturer or an administrator may take the register' using errcode = '42501';
  end if;
  if jsonb_typeof(p_entries) <> 'array' or jsonb_array_length(p_entries) = 0 or jsonb_array_length(p_entries) > 3000 then
    raise exception 'nothing to save';
  end if;
  if s.status <> 'open' and length(trim(coalesce(p_note, ''))) < 3 then
    raise exception 'This session is closed: give a reason for the changes.' using errcode = 'P0001';
  end if;
  select coalesce(nullif(p.full_name, ''), p.email, 'Lecturer') into v_by from uniattend.profiles p where p.id = auth.uid();

  for e in select value from jsonb_array_elements(p_entries) loop
    v_student := (e->>'student')::uuid;
    v_status := e->>'status';
    v_custom := nullif(e->>'custom', '')::uuid;
    v_note := coalesce(nullif(trim(e->>'note'), ''), nullif(trim(p_note), ''));
    if v_status not in ('present','late','absent','excused') then raise exception 'not a status a person may set: %', v_status; end if;
    if v_custom is not null then
      -- A custom status must belong to this institution and decides the category.
      select category into v_status from uniattend.attendance_statuses
       where id = v_custom and institution_id = s.institution_id and active;
      if v_status is null then raise exception 'unknown attendance status'; end if;
    end if;
    if not exists (select 1 from uniattend.module_enrolments where module_id = s.module_id and student_id = v_student) then
      raise exception 'a student in the list is not enrolled in this module';
    end if;

    select * into prev from uniattend.attendance_records where session_id = s.id and student_id = v_student;
    if prev.id is not null and prev.status = v_status and prev.custom_status_id is not distinct from v_custom then
      skipped := skipped + 1; continue;
    end if;

    insert into uniattend.attendance_records as ar (institution_id, session_id, module_id, student_id, status, custom_status_id, method,
                                                    checked_in_at, overridden_by, overridden_at, override_note)
    values (s.institution_id, s.id, s.module_id, v_student, v_status, v_custom, 'manual',
            case when v_status in ('present','late') then now() end, auth.uid(), now(), coalesce(v_note, 'Register taken by the lecturer.'))
    on conflict (session_id, student_id) do update
      set status = excluded.status, custom_status_id = excluded.custom_status_id,
          overridden_by = excluded.overridden_by, overridden_at = excluded.overridden_at, override_note = excluded.override_note
    returning * into r;

    insert into uniattend.attendance_evidence (institution_id, record_id, kind, data)
    values (s.institution_id, r.id, 'manual', jsonb_build_object(
      'from', prev.status, 'from_custom', prev.custom_status_id, 'to', v_status, 'to_custom', v_custom,
      'note', coalesce(v_note, 'Register taken by the lecturer.'), 'by', auth.uid(), 'by_name', v_by, 'session_open', s.status = 'open'));

    -- Tell the student when a closed record is corrected (not for the live register).
    if s.status <> 'open' then
      select user_id into uid from uniattend.students where id = v_student;
      if uid is not null then
        insert into uniattend.notifications (institution_id, user_id, kind, title, body, link)
        values (s.institution_id, uid, 'attendance_corrected', 'Attendance updated',
                'Your attendance for ' || s.title || ' was set to ' ||
                coalesce((select name from uniattend.attendance_statuses where id = v_custom), v_status) || '.', '/student/history');
      end if;
    end if;
    changed := changed + 1;
  end loop;

  perform uniattend.write_audit(s.institution_id, 'register', 'class_sessions', s.id::text,
                             jsonb_build_object('changed', changed, 'unchanged', skipped));
  return jsonb_build_object('changed', changed, 'unchanged', skipped);
end $$;

-- ---------------------------------------------------------------- history
-- Everything that happened to one record: check-in attempts and manual changes, oldest first.
create or replace function uniattend.record_history(p_record uuid)
returns table (at timestamptz, kind text, summary text, by_name text, note text)
language plpgsql stable security definer set search_path = '' as $$
declare r uniattend.attendance_records;
begin
  select * into r from uniattend.attendance_records where id = p_record;
  if r is null or not (uniattend.teaches_module(r.module_id) or uniattend.is_inst_admin(r.institution_id)
                       or uniattend.is_own_student(r.student_id)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  select v.created_at, 'check_in'::text,
         initcap(v.outcome) || ' · score ' || v.score, null::text,
         nullif(array_to_string(array(select jsonb_array_elements_text(v.reasons)), ' '), '')
  from uniattend.attendance_verification_events v
  where v.session_id = r.session_id and v.student_id = r.student_id
  union all
  select ev.created_at, 'change'::text,
         case when ev.data ? 'from' then coalesce(
                (select name from uniattend.attendance_statuses where id = (ev.data->>'from_custom')::uuid), ev.data->>'from', 'none')
              || ' → ' ||
              coalesce((select name from uniattend.attendance_statuses where id = (ev.data->>'to_custom')::uuid), ev.data->>'to')
              else 'Set to ' || coalesce(ev.data->>'status', '?') end,
         coalesce(ev.data->>'by_name', 'Staff'), ev.data->>'note'
  from uniattend.attendance_evidence ev
  where ev.record_id = r.id and ev.kind = 'manual'
  union all
  select d.created_at, 'dispute'::text, 'Dispute ' || d.status, null::text, d.reason
  from uniattend.attendance_disputes d where d.record_id = r.id
  order by 1;
end $$;

-- ------------------------------------------------------------------ grants
revoke all on function uniattend.save_register(uuid, jsonb, text) from public, anon;
revoke all on function uniattend.record_history(uuid) from public, anon;
revoke all on function uniattend.seed_attendance_statuses() from public, anon;
grant execute on function uniattend.save_register(uuid, jsonb, text) to authenticated;
grant execute on function uniattend.record_history(uuid) to authenticated;

commit;
